// === ESTRUCTURA DEL PATRÓN FACADE ===

// 1. Subsistema — clases complejas
class Amplifier {
  on() { console.log('Amplificador encendido'); }
  off() { console.log('Amplificador apagado'); }
  setVolume(level: number) { console.log('Volumen: ' + level); }
}

class Projector {
  on() { console.log('Proyector encendido'); }
  off() { console.log('Proyector apagado'); }
  setInput(input: string) { console.log('Input: ' + input); }
  setWideScreen() { console.log('Modo panorámico'); }
}

class Screen {
  up() { console.log('Pantalla subiendo'); }
  down() { console.log('Pantalla bajando'); }
}

class SoundSystem {
  on() { console.log('Sonido encendido'); }
  off() { console.log('Sonido apagado'); }
  setSurround() { console.log('Sonido surround activado'); }
}

// 2. Fachada — interfaz simplificada
class HomeTheaterFacade {
  private amp = new Amplifier();
  private projector = new Projector();
  private screen = new Screen();
  private sound = new SoundSystem();

  watchMovie(movie: string) {
    console.log('Preparando ' + movie + '...');
    this.screen.down();
    this.projector.on();
    this.projector.setInput('DVD');
    this.projector.setWideScreen();
    this.sound.on();
    this.sound.setSurround();
    this.amp.on();
    this.amp.setVolume(8);
    console.log('Reproduciendo ' + movie);
  }

  endMovie() {
    console.log('Apagando sistema...');
    this.amp.off();
    this.sound.off();
    this.projector.off();
    this.screen.up();
    console.log('Sistema apagado');
  }
}

// Uso:
const theater = new HomeTheaterFacade();
theater.watchMovie('Inception');
// ... 2 horas después ...
theater.endMovie();

